\subsection{Coordination-Aware Self-Attention}
% NOTION N-M13; USER U-29/U-30: author narrative, equations, and concise prose.
Coordination in humanoid loco-manipulation is inherently directional and state dependent, requiring compensatory body motions when arm manipulability along the task direction becomes insufficient. We therefore introduce a \textbf{coordination-aware self-attention mechanism} that selectively strengthens manipulation-to-UWBC information flow.

% Keep Table I in the right column opposite Fig. 3.
% NOTION N-T01
\suppressfloats[t]


% NOTION N-M14
\textit{Gated attention logit bias.} The native self-attention logits are modified as follows:
% NOTION N-E05
\begin{equation}
\mathbf L'_t=\frac{\mathbf Q\mathbf K^\top}{\sqrt d}
 +\mathbf M^{\mathrm{nat}}
 +\beta g_t\mathbf S^{M\rightarrow U}.
\label{eq:logit}
\end{equation}
Here $\mathbf Q$ and $\mathbf K$ denote the query and key matrices, $d$ denotes the head dimension, and $\mathbf M^{\mathrm{nat}}$ represents the native self-attention mask. The coordination gate $g_t\in[0,1]$ scales a fixed bias of strength $\beta>0$. As illustrated in Fig.~\ref{fig:attention}, the selector $S_{ij}^{M\rightarrow U}=1$ only when $i$ is a UWBC query and $j$ is a manipulation key in the same prediction block.

% NOTION N-M15--N-M17; USER 2026-09-10: observed direction and local voxel reference.
\textit{Coordination gate computation.} The gate $g_t$ evaluates reduced task-directional manipulability in the current arm configurations to determine whether whole-body coordination is needed. First, for each arm $a\in\{L,R\}$, the task direction is calculated from consecutive observed end-effector positions during motion:
\begin{equation}
 \mathbf v_{a,t}
 =\frac{\mathbf p_{a,t}-\mathbf p_{a,t-1}}{\Delta t},
 \qquad
 \hat{\mathbf d}_{a,t}
 =\frac{\mathbf v_{a,t}}{\|\mathbf v_{a,t}\|_2}.
 \label{eq:task_direction}
\end{equation}
Here $\mathbf p_{a,t}$ denotes the observed end-effector position, $\Delta t$ denotes the observation interval, and $\mathbf v_{a,t}$ denotes the observed end-effector velocity. The unit vector $\hat{\mathbf d}_{a,t}$ represents the estimated task direction.
The manipulability of each arm configuration along this task direction is then calculated as
\begin{equation}
 c_{a,t}
 =\left[\hat{\mathbf d}_{a,t}^{\top}
 \bigl(C_a^{v,\lambda}(\mathbf q^{\mathrm{obs}}_{a,t})\bigr)^{-1}
 \hat{\mathbf d}_{a,t}\right]^{-1/2}.
 \label{eq:directional_capability}
\end{equation}
Here $C_a^{v,\lambda}\in\mathbb R^{3\times3}$ denotes the damped manipulability matrix incorporating joint speed limits, and $\mathbf q^{\mathrm{obs}}_{a,t}$ denotes the observed arm joint configuration.
We construct a voxelized manipulability map offline following~\cite{vahrenkamp2012}. At runtime, the reference $c^{\mathrm{ref}}_{a,t}$ is the maximum sampled radial capability along the estimated task direction among configurations in the current end-effector pose voxel. The gate for each arm is then calculated from the relative reduction in manipulability:
\begin{equation}
 g_{a,t}=1-\operatorname{clip}\!\left(
 \frac{c_{a,t}}{c^{\mathrm{ref}}_{a,t}+\epsilon_m},0,1\right),
 \label{eq:arm_gate}
\end{equation}
where $\epsilon_m>0$ is a small constant that prevents division by zero. Finally, the global gate for both arms takes the larger relative reduction:
\begin{equation}
 g_t^{M\rightarrow U}=\max(g_{L,t},g_{R,t}).
 \label{eq:gate}
\end{equation}
This ensures that reduced task-directional manipulability in either active arm can trigger manipulation-to-UWBC coordination.

